1	package shadow
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"sort"
7		"time"
8	)
9	
10	// 升级阶段标识。
11	const (
12		StageDownload = "download"
13		StageInstall  = "install"
14		StageRollback = "rollback"
15	)
16	
17	// 活动与设备在活动中的状态。
18	const (
19		CampaignRunning   = "running"
20		CampaignSucceeded = "succeeded"
21		CampaignFailed    = "failed"
22	
23		DevicePending     = "pending"     // 尚未领取下载
24		DeviceDownloading = "downloading" // 已领取下载，未完成
25		DeviceReady       = "ready"       // 下载成功，安装尚未领取
26		DeviceInstalling  = "installing"  // 已领取安装，未完成
27		DeviceSucceeded   = "succeeded"
28		DeviceFailed      = "failed"
29		DeviceTimeout     = "timeout"
30		DeviceSkipped     = "skipped" // 前序批次失败后，后续批次记为未执行
31	
32		// 回滚相关状态，仅出现在开启回滚的活动中。
33		DeviceAwaitingRollback  = "awaiting_rollback" // 安装失败已接受，等待领取回滚
34		DeviceRollingBack       = "rolling_back"      // 已领取回滚，未完成
35		DeviceRollbackSucceeded = "rollback_succeeded"
36		DeviceRollbackFailed    = "rollback_failed"
37		DeviceRollbackTimeout   = "rollback_timeout" // 到达截止时间时回滚仍未完成
38	)
39	
40	// VersionSpec 是一个已登记的升级目标版本及其允许的当前版本。
41	type VersionSpec struct {
42		// Target 是目标版本，与设备当前版本按字符串精确匹配。
43		Target string
44		// AllowedFrom 是允许升级到目标版本的当前版本列表。
45		AllowedFrom []string
46	}
47	
48	// versionState 是升级版本登记的内部状态。
49	type versionState struct {
50		Target      string
51		AllowedFrom []string
52	}
53	
54	// CampaignSpec 描述创建分批升级活动所需的全部信息。
55	type CampaignSpec struct {
56		// ID 是活动唯一标识，不能为空。
57		ID string
58		// Operator 是创建活动的操作者，不能为空。
59		Operator string
60		// CreatedAt 是活动创建时间。
61		CreatedAt time.Time
62		// TargetVersion 是已登记的目标版本。
63		TargetVersion string
64		// Devices 是按提交次序排列的有序设备列表，不能为空、不能重复。
65		Devices []string
66		// BatchSize 是批大小，必须是正整数。
67		BatchSize int
68		// WindowStart/WindowEnd 是维护窗口，开始时刻须早于结束时刻；
69		// 窗口包含开始时刻、不包含结束时刻。
70		WindowStart time.Time
71		WindowEnd   time.Time
72		// Deadline 是截止时间，必须晚于创建时间。
73		Deadline time.Time
74		// RollbackOnFailure 开启安装失败后的自动回滚，默认关闭。
75		// 关闭时安装失败即设备失败；开启后安装失败会先等待设备回滚到
76		// 首次领取下载时锁定的当前版本，活动最终仍为失败。
77		RollbackOnFailure bool
78	}
79	
80	// Operation 是派发给设备的一个升级操作。
81	type Operation struct {
82		// ID 是操作的稳定标识，重复查询未完成操作时保持不变，重开存储后仍有效。
83		ID         string
84		CampaignID string
85		DeviceID   string
86		// Kind 是 StageDownload、StageInstall 或 StageRollback。
87		Kind string
88		// TargetVersion 仅在回滚操作上有值，指明必须恢复到的锁定版本，
89		// 让设备明确知道要恢复哪个版本；下载与安装操作为空。
90		TargetVersion string
91	}
92	
93	// OperationResult 是设备提交的一次操作结果。
94	// 每次结果必须带活动、设备、操作标识及发生时间。
95	// 安装成功（Success 且操作是 install）时还须附带符合上报规则的设备上报：
96	// 正整数 Seq、等于目标版本的 Version 和完整 JSON 对象 Config。
97	// 回滚成功（Success 且操作是 rollback）时同样须附带上报，
98	// 但 Version 必须等于领取下载时锁定的回滚目标版本。
99	type OperationResult struct {
100		CampaignID  string
101		DeviceID    string
102		OperationID string
103		At          time.Time
