182	// RegisterUpgrade 登记一个升级目标版本及允许升级的当前版本列表。
183	// 版本字符串精确匹配；列表不能为空、不能含空串、不能包含目标版本。
184	// 目标版本重复登记时返回 ErrVersionExists 并保留原记录。
185	func (s *Store) RegisterUpgrade(targetVersion string, allowedFrom []string) error {
186		s.mu.Lock()
187		defer s.mu.Unlock()
188		if err := s.checkOpen(); err != nil {
189			return err
190		}
191		if targetVersion == "" {
192			return ErrInvalidVersion
193		}
194		if err := validateAllowedFrom(targetVersion, allowedFrom); err != nil {
195			return err
196		}
197		if _, ok := s.versions[targetVersion]; ok {
198			return fmt.Errorf("%w: %s", ErrVersionExists, targetVersion)
199		}
200		from := append([]string(nil), allowedFrom...)
201		return s.commit(func() error {
202			s.versions[targetVersion] = &versionState{Target: targetVersion, AllowedFrom: from}
203			return nil
204		})
205	}
206	
207	func validateAllowedFrom(target string, allowedFrom []string) error {
208		if len(allowedFrom) == 0 {
209			return fmt.Errorf("%w: list is empty", ErrInvalidVersionList)
210		}
211		for _, v := range allowedFrom {
212			if v == "" {
213				return fmt.Errorf("%w: contains empty version", ErrInvalidVersionList)
214			}
215			if v == target {
216				return fmt.Errorf("%w: contains target version %s", ErrInvalidVersionList, target)
217			}
218		}
219		return nil
220	}
