946	// DeviceStatusView 是一台设备在活动中的状态快照。
947	type DeviceStatusView struct {
948		DeviceID string
949		Batch    int
950		// Status 取 Device* 状态常量，含等待回滚、正在回滚、回滚成功、
951		// 回滚失败与回滚阶段超时。
952		Status string
953		// Phase 是设备当前停留或失败的阶段（download/install/rollback）。
954		Phase string
955		// Reason 是失败、超时或未执行（skipped）的原因；成功时为空。
956		Reason string
957		// At 是进入当前状态的时间。
958		At time.Time
959		// DownloadID/InstallID/RollbackID 是各阶段操作的稳定标识。
960		DownloadID string
961		InstallID  string
962		RollbackID string
963		// RollbackTarget 是开启回滚时首次领取下载锁定的回滚目标版本；未锁定为空。
964		RollbackTarget string
965		// InstallFailReason/InstallFailAt 是已接受的安装失败的原因与时间，
966		// 进入回滚后仍保留原值，便于与回滚结果分别查看。
967		InstallFailReason string
968		InstallFailAt     time.Time
969		// RollbackResult 表示是否已接受回滚结果。
970		RollbackResult bool
971		// RollbackSuccess 表示已接受的回滚结果是否成功。
972		RollbackSuccess bool
973		// RollbackReason/RollbackAt 是回滚结果（成功或失败）的原因与时间。
974		RollbackReason string
975		RollbackAt     time.Time
976	}
977	
978	// BatchView 是一个批次内所有设备的状态，按提交次序排列。
979	type BatchView struct {
980		Index   int
981		Devices []DeviceStatusView
982	}
