986		ID            string
987		Operator      string
988		TargetVersion string
989		CreatedAt     time.Time
990		BatchSize     int
991		WindowStart   time.Time
992		WindowEnd     time.Time
993		Deadline      time.Time
994		// RollbackOnFailure 表示该活动是否开启安装失败回滚。
995		RollbackOnFailure bool
996		// Status 取 Campaign* 状态常量。
997		Status  string
998		Ended   bool
999		EndedAt time.Time
1000		// Devices 按提交次序给出每台设备的状态。
