1070	// DeviceWork 是设备当前版本与待执行操作的查询结果。
1071	type DeviceWork struct {
1072		DeviceID string
1073		Version  string
1074		Online   bool
1075		// CampaignID 是设备当前所在的未结束活动；没有时为空。
1076		CampaignID string
1077		// Pending 是设备仍待完成的操作（至多一个）：已领取未完成或下一阶段可领取。
1078		// 等待回滚时为尚未领取的回滚操作，其 TargetVersion 给出锁定的回滚目标。
1079		Pending *Operation
1080		// PendingClaimed 表示 Pending 是否已领取（未领取的安装或回滚仍须等维护窗口）。
1081		PendingClaimed bool
1082	}
1083	
1084	// GetDeviceWork 查询设备当前版本及其待执行操作。
1085	func (s *Store) GetDeviceWork(deviceID string) (DeviceWork, error) {
1086		s.mu.Lock()
1087		defer s.mu.Unlock()
1088		if err := s.checkOpen(); err != nil {
1089			return DeviceWork{}, err
1090		}
1091		d, err := s.lookup(deviceID)
1092		if err != nil {
1093			return DeviceWork{}, err
1094		}
1095		w := DeviceWork{DeviceID: deviceID, Version: d.Version, Online: d.Online}
1096		for id, c := range s.campaigns {
1097			if c.Ended {
1098				continue
1099			}
1100			i, ok := c.index[deviceID]
1101			if !ok {
1102				continue
1103			}
1104			cd := c.Devices[i]
1105			w.CampaignID = id
1106			if out := outstandingOp(c, cd); out != nil {
1107				w.Pending = out
1108				w.PendingClaimed = true
1109			} else if cd.Status == DeviceAwaitingRollback {
1110				// 回滚待领取：显示回滚目标，标记为尚未领取。
1111				w.Pending = &Operation{
1112					ID:            cd.Rollback.ID,
1113					CampaignID:    c.ID,
1114					DeviceID:      deviceID,
1115					Kind:          StageRollback,
1116					TargetVersion: cd.RollbackTarget,
1117				}
1118				w.PendingClaimed = false
1119			} else if !isTerminal(cd.Status) {
1120				kind := StageDownload
1121				id := cd.Download.ID
1122				if cd.Download.HasResult {
1123					kind, id = StageInstall, cd.Install.ID
1124				}
1125				w.Pending = &Operation{ID: id, CampaignID: c.ID, DeviceID: deviceID, Kind: kind}
1126				w.PendingClaimed = false
1127			}
1128			break
1129		}
1130		return w, nil
1131	}
1132	
1133	// ListUpgrades 返回已登记的全部升级目标版本，按目标版本字典序排列。
1134	func (s *Store) ListUpgrades() ([]VersionSpec, error) {
1135		s.mu.Lock()
1136		defer s.mu.Unlock()
1137		if err := s.checkOpen(); err != nil {
1138			return nil, err
1139		}
1140		out := make([]VersionSpec, 0, len(s.versions))
1141		for _, v := range s.versions {
1142			out = append(out, VersionSpec{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)})
1143		}
1144		sort.Slice(out, func(i, j int) bool { return out[i].Target < out[j].Target })
1145		return out, nil
1146	}
