	return decodeObject(raw)
}

// assertSingleValue 确认解码器读完一个完整 JSON 值后只剩 JSON 空白：
// 第二个值解码成功（err == nil）或尾随文本无法解析（任何非 io.EOF 错误）
// 都表示输入不是单一 JSON 值，必须拒绝。
func assertSingleValue(dec *json.Decoder) error {
