273		s := setupUpgrade(t, "d1")
274		spec := upSpec()
275		spec.Devices = []string{"d1"}
276		spec.BatchSize = 1
277		createCampaign(t, s, spec)
278		bringOnline(t, s, "d1")
279		in := claimInstall(t, s, spec, "d1", upBase.Add(2*time.Minute))
280		installAt := upBase.Add(5 * time.Minute)
281		first := OperationResult{
282			CampaignID: spec.ID, DeviceID: "d1", OperationID: in,
283			At: installAt, Success: true,
284			Seq: 2, Version: "v2", Config: json.RawMessage(`{"a":1,"b":2}`),
285		}
286		if err := s.SubmitResult(first); err != nil {
287			t.Fatalf("first install: %v", err)
288		}
289		cv, _ := s.GetCampaign(spec.ID)
290		nResults := len(cv.Results)
291	
292		// 追加非空白内容：冲突，历史不增加。
293		for _, cfg := range []string{`{"a":1,"b":2} null`, `{"a":1,"b":2}z`} {
294			bad := first
295			bad.Config = json.RawMessage(cfg)
296			if err := s.SubmitResult(bad); !errors.Is(err, ErrResultConflict) {
297				t.Fatalf("replay %q: got %v, want ErrResultConflict", cfg, err)
298			}
299		}
300		cv, _ = s.GetCampaign(spec.ID)
301		if len(cv.Results) != nResults {
302			t.Fatalf("history changed on conflicting replay: %+v", cv.Results)
303		}
304		if d := findDevice(cv, "d1"); d.Status != DeviceSucceeded {
305			t.Fatalf("accepted result altered: %+v", d)
306		}
307		shadow, _ := s.Get("d1")
308		if shadow.Version != "v2" || string(shadow.Reported) != `{"a":1,"b":2}` {
309			t.Fatalf("shadow altered by conflict: %+v", shadow)
310		}
311	
312		// 设备随后普通上报更大序号；活动在单设备成功后已经结束。
313		if err := s.Report("d1", 3, upBase.Add(20*time.Minute), "v2", json.RawMessage(`{"later":true}`)); err != nil {
314			t.Fatal(err)
315		}
316		// 合法重发（字段顺序、空白、等值数字不同）仍依据已接受结果成功。
317		legal := first
318		legal.At = upBase.Add(3 * time.Hour)
319		legal.Config = json.RawMessage(`{ "b": 2.0, "a": 1 }`)
320		if err := s.SubmitResult(legal); err != nil {
321			t.Fatalf("legal replay after larger seq / campaign end: %v", err)
322		}
323		cv, _ = s.GetCampaign(spec.ID)
324		if len(cv.Results) != nResults {
325			t.Fatal("legal replay added history")
326		}
327	}
328	
329	// 首次提交的回滚成功结果附带尾随内容：返回 ErrInvalidReport，设备仍停在
330	// rolling_back，影子与历史不变；合法配置随后可成功。
331	func TestRollbackSuccessTrailingConfigFirstTime(t *testing.T) {
332		s := setupUpgrade(t, "d1")
333		spec := rbSpec()
334		createCampaign(t, s, spec)
335		bringOnline(t, s, "d1")
336		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
337		rb, err := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
338		if err != nil || rb == nil || rb.Kind != StageRollback {
339			t.Fatalf("claim rollback: %v %+v", err, rb)
340		}
341		cv0, _ := s.GetCampaign(spec.ID)
342		nResults := len(cv0.Results)
343	
344		for _, cfg := range []string{`{} null`, `{"a":1} {}`} {
345			err := s.SubmitResult(OperationResult{
346				CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
347				At: upBase.Add(9 * time.Minute), Success: true,
348				Seq: 2, Version: "v1", Config: json.RawMessage(cfg),
349			})
350			if !errors.Is(err, ErrInvalidReport) {
351				t.Fatalf("config %q: got %v, want ErrInvalidReport", cfg, err)
352			}
353		}
354		cv, _ := s.GetCampaign(spec.ID)
355		if d := findDevice(cv, "d1"); d.Status != DeviceRollingBack {
356			t.Fatalf("device advanced on invalid rollback report: %s", d.Status)
357		}
358		if len(cv.Results) != nResults {
359			t.Fatal("history changed on invalid rollback report")
360		}
361	
362		if err := s.SubmitResult(OperationResult{
363			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
364			At: upBase.Add(9 * time.Minute), Success: true,
365			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
366		}); err != nil {
367			t.Fatalf("legal rollback: %v", err)
368		}
369	}
370	
371	// 已接受的回滚成功结果重发时追加非空白内容：返回 ErrResultConflict；
372	// 合法重发（空白/字段顺序/数字等值）在设备上报更大序号后仍成功。
373	func TestRollbackSuccessReplayTrailingConflicts(t *testing.T) {
374		s := setupUpgrade(t, "d1")
375		spec := rbSpec()
376		createCampaign(t, s, spec)
377		bringOnline(t, s, "d1")
378		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
379		rb, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
380		first := OperationResult{
381			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
382			At: upBase.Add(9 * time.Minute), Success: true,
383			Seq: 2, Version: "v1", Config: json.RawMessage(`{"a":1,"b":2}`),
384		}
385		if err := s.SubmitResult(first); err != nil {
386			t.Fatalf("first rollback: %v", err)
387		}
388		cv, _ := s.GetCampaign(spec.ID)
389		nResults := len(cv.Results)
390	
391		bad := first
392		bad.Config = json.RawMessage(`{"a":1,"b":2} null`)
393		if err := s.SubmitResult(bad); !errors.Is(err, ErrResultConflict) {
394			t.Fatalf("rollback replay trailing: got %v, want ErrResultConflict", err)
395		}
396		cv, _ = s.GetCampaign(spec.ID)
397		if len(cv.Results) != nResults {
398			t.Fatal("conflicting rollback replay added history")
399		}
400		if d := findDevice(cv, "d1"); d.Status != DeviceRollbackSucceeded {
401			t.Fatalf("accepted rollback altered: %+v", d)
402		}
403	
404		// 设备后来普通上报更大序号（版本偏离锁定目标也不影响幂等判断）。
405		if err := s.Report("d1", 3, upBase.Add(20*time.Minute), "v9", json.RawMessage(`{"x":1}`)); err != nil {
406			t.Fatal(err)
407		}
408		legal := first
409		legal.At = upBase.Add(30 * time.Minute)
410		legal.Config = json.RawMessage(`{ "b": 2, "a": 1.0 }`)
411		if err := s.SubmitResult(legal); err != nil {
412			t.Fatalf("legal rollback replay: %v", err)
413		}
414		cv, _ = s.GetCampaign(spec.ID)
415		if len(cv.Results) != nResults {
416			t.Fatal("legal rollback replay added history")
417		}
418	}
419	
420	// 已领取安装但尚未接受结果，到达截止时间时提交附带非法配置的成功结果：
421	// 仍按截止结束活动并返回 ErrCampaignEnded，不改成配置错误；设备超时、
422	// 结果历史与影子均不变。
423	func TestClaimedInstallInvalidConfigAtDeadline(t *testing.T) {
424		s := setupUpgrade(t, "d1")
425		spec := upSpec()
426		spec.Devices = []string{"d1"}
427		spec.BatchSize = 1
428		createCampaign(t, s, spec)
429		bringOnline(t, s, "d1")
430		in := claimInstall(t, s, spec, "d1", upBase.Add(5*time.Minute))
431		shadowBefore, _ := s.Get("d1")
432		cv0, _ := s.GetCampaign(spec.ID)
433		nResults := len(cv0.Results)
434	
435		err := s.SubmitResult(OperationResult{
436			CampaignID: spec.ID, DeviceID: "d1", OperationID: in,
437			At: upBase.Add(2 * time.Hour), Success: true,
438			Seq: 2, Version: "v2", Config: json.RawMessage(`{"ok":true} null`),
439		})
440		if !errors.Is(err, ErrCampaignEnded) {
441			t.Fatalf("got %v, want ErrCampaignEnded", err)
442		}
443		cv, _ := s.GetCampaign(spec.ID)
444		if !cv.Ended || cv.Status != CampaignFailed {
445			t.Fatalf("campaign: %+v", cv)
446		}
447		if d := findDevice(cv, "d1"); d.Status != DeviceTimeout || d.Phase != StageInstall {
448			t.Fatalf("device record: %+v", d)
449		}
450		if len(cv.Results) != nResults {
451			t.Fatal("late result entered history")
452		}
453		after, _ := s.Get("d1")
454		if after.LastSeq != shadowBefore.LastSeq || after.Version != shadowBefore.Version ||
455			string(after.Reported) != string(shadowBefore.Reported) {
456			t.Fatalf("shadow changed: before %+v after %+v", shadowBefore, after)
457		}
458	}
459	
460	// 活动已被显式推进到截止而结束后，已领取但未接受的安装结果（带非法配置）
461	// 仍返回 ErrCampaignEnded，而不是 ErrInvalidReport。
462	func TestClaimedInstallInvalidConfigAfterAdvanceDeadline(t *testing.T) {
463		s := setupUpgrade(t, "d1")
464		spec := upSpec()
465		spec.Devices = []string{"d1"}
466		spec.BatchSize = 1
467		createCampaign(t, s, spec)
468		bringOnline(t, s, "d1")
469		in := claimInstall(t, s, spec, "d1", upBase.Add(5*time.Minute))
470	
471		if err := s.AdvanceCampaign(spec.ID, upBase.Add(2*time.Hour)); err != nil {
472			t.Fatal(err)
473		}
474		err := s.SubmitResult(OperationResult{
475			CampaignID: spec.ID, DeviceID: "d1", OperationID: in,
476			At: upBase.Add(2*time.Hour + time.Minute), Success: true,
477			Seq: 2, Version: "v2", Config: json.RawMessage(`{"ok":true} null`),
478		})
479		if !errors.Is(err, ErrCampaignEnded) {
480			t.Fatalf("got %v, want ErrCampaignEnded", err)
481		}
482		cv, _ := s.GetCampaign(spec.ID)
483		if d := findDevice(cv, "d1"); d.Status != DeviceTimeout {
484			t.Fatalf("device record: %+v", d)
