507		if err := s.SubmitResult(OperationResult{
508			CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
509			At: upBase.Add(3 * time.Minute), Success: false, Reason: "install boom",
510		}); err != nil {
511			t.Fatalf("install failure: %v", err)
512		}
513		return s, s.dir, spec, &Operation{ID: operationID(spec.ID, "d1", StageRollback)}
514	}
